Deno.serve(async (req) => {
  try {
    const base44 = createClientFromRequest(req);
    const user = await base44.auth.me();
    if (user?.role !== 'admin') {
      return Response.json({ error: 'Admin only' }, { status: 403 });
    }

    // Fetch all existing users by email for dedup (paginate to get all)
    let existingUsers = [];
    let page1 = await base44.asServiceRole.entities.User.list('-created_date', 5000);
    existingUsers = existingUsers.concat(page1);
    if (page1.length === 5000) {
      // There may be more — fetch another page
      let page2 = await base44.asServiceRole.entities.User.list('created_date', 5000);
      existingUsers = existingUsers.concat(page2);
    }
    const existingEmails = new Set(existingUsers.map(u => u.email?.toLowerCase().trim()).filter(Boolean));

    let created = 0;
    let skipped = 0;
    let noSchool = 0;
    const errors = [];
    const createdList = [];

    for (const row of CSV_USERS) {
      const email = row.email?.toLowerCase().trim();
      if (!email) { skipped++; continue; }

      // Skip if already in DB
      if (existingEmails.has(email)) { skipped++; continue; }

      // Skip Apple private relay and temp addresses
      if (email.includes('privaterelay.appleid.com') || email.includes('@gtempaccount.com')) { skipped++; continue; }

      // Skip if no school
      const schoolCode = row.school?.toLowerCase().trim();
      if (!schoolCode || !SCHOOL_MAP[schoolCode]) { noSchool++; continue; }

      const school = SCHOOL_MAP[schoolCode];

      // Build clean name
      let fullName = row.full_name?.trim();
      if (!fullName || fullName === email || fullName.includes('@')) {
        // Try to derive from email prefix
        const prefix = email.split('@')[0];
        fullName = prefix.replace(/[._-]+/g, ' ').replace(/\b\w/g, c => c.toUpperCase()).trim();
      }

      const isParent = row.persona === 'parent';
      const isAlumni = row.persona === 'alumni';

      const userData = {
        full_name: fullName,
        email: email,
        persona: row.persona,
        roles: [row.persona],
        onboarding_completed: row.onboarding_completed === true,
        school_code: school.code,
        school_name: school.name,
        school: school.name,
        company: row.company || '',
        current_company: row.company || '',
        job_title: row.job_title || '',
        current_position: row.job_title || '',
        industry: row.industry || '',
        linkedin_url: row.linkedin_url || '',
        bio: row.bio || '',
        visible_in_directory: true,
        intro_willingness: 'yes',
        is_founding_member: true,
        source: 'csv_import_2026_04',
        ...(isAlumni ? {
          alumni_intent: 'giving_help',
        } : {}),
        ...(isParent ? {
          alumni_intent: 'help_students',
        } : {}),
      };

      try {
        await base44.asServiceRole.entities.User.create(userData);
        created++;
        createdList.push({ email, school: school.code, persona: row.persona });
      } catch (err) {
        errors.push({ email, error: err.message });
      }

      // Small delay to avoid rate limits
      if (created % 15 === 0) {
        await new Promise(r => setTimeout(r, 300));
      }
    }

    // Summary by school
    const bySchool = {};
    for (const u of createdList) {
      bySchool[u.school] = (bySchool[u.school] || 0) + 1;
    }

    return Response.json({
      success: true,
      created,
      skipped,
      no_school: noSchool,
      errors: errors.slice(0, 20),
      by_school: bySchool,
    });

  } catch (error) {
    return Response.json({ error: error.message }, { status: 500 });
  }
});